const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("pcsAcMeasState") || {
    kind: "PcsAcMeasState",
    version: 1,
    // PCS_MEAS_1 (0x66B966x)
    pcs_abLineV: null,
    pcs_bcLineV: null,
    pcs_acLineV: null,
    pcs_aPhaseV: null,
    // PCS_MEAS_2 (0x66B967x)
    pcs_bPhaseV: null,
    pcs_cPhaseV: null,
    pcs_aPhaseCurrA: null,
    pcs_bPhaseCurrA: null,
    // PCS_MEAS_3 (0x66B968x)
    pcs_cPhaseCurrA: null,
    pcs_aPhIndCurrA: null,
    pcs_bPhIndCurrA: null,
    pcs_cPhIndCurrA: null
};

// Helper function
function s16(buf, offset) {
    let val = (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
    return val > 32767 ? val - 65536 : val;
}

var processed = false;

// ==================== PCS_MEAS_1 (0x66B966x) ====================
if ((canId & 0xFFFFFFF0) === 0x66B9660) {
    processed = true;

    // Bit 0-15: AB Line Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_abLineV = s16(data, 0) * 0.1;

    // Bit 16-31: BC Line Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_bcLineV = s16(data, 2) * 0.1;

    // Bit 32-47: AC Line Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_acLineV = s16(data, 4) * 0.1;

    // Bit 48-63: A Phase Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_aPhaseV = s16(data, 6) * 0.1;
}

// ==================== PCS_MEAS_2 (0x66B967x) ====================
if ((canId & 0xFFFFFFF0) === 0x66B9670) {
    processed = true;

    // Bit 0-15: B Phase Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_bPhaseV = s16(data, 0) * 0.1;

    // Bit 16-31: C Phase Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_cPhaseV = s16(data, 2) * 0.1;

    // Bit 32-47: A Phase Current
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: A
    // Min: -3276.8, Max: 3276.7
    state.pcs_aPhaseCurrA = s16(data, 4) * 0.1;

    // Bit 48-63: B Phase Current
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: A
    // Min: -3276.8, Max: 3276.7
    state.pcs_bPhaseCurrA = s16(data, 6) * 0.1;
}

// ==================== PCS_MEAS_3 (0x66B968x) ====================
if ((canId & 0xFFFFFFF0) === 0x66B9680) {
    processed = true;

    // Bit 0-15: C Phase Current
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: A
    // Min: -3276.8, Max: 3276.7
    state.pcs_cPhaseCurrA = s16(data, 0) * 0.1;

    // Bit 16-31: A Phase Inductor Current
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: A
    // Min: -3276.8, Max: 3276.7
    state.pcs_aPhIndCurrA = s16(data, 2) * 0.1;

    // Bit 32-47: B Phase Inductor Current
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: A
    // Min: -3276.8, Max: 3276.7
    state.pcs_bPhIndCurrA = s16(data, 4) * 0.1;

    // Bit 48-63: C Phase Inductor Current
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: A
    // Min: -3276.8, Max: 3276.7
    state.pcs_cPhIndCurrA = s16(data, 6) * 0.1;
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("pcsAcMeasState", state);
msg.payload = state;
return msg;

var state = flow.get("pcsAcMeasState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
